import queue
import threading
import time


class Controller:
    """Manages worker threads pulling items from a shared queue.

    - pause(): workers finish their current (in-flight) item, then stop
      taking new items.
    - resume(): workers start taking items again.
    - stop(): terminates all workers cleanly; joinable without daemon threads.
    """

    def __init__(self, num_workers: int = 3, work_seconds: float = 0.0):
        self.queue: queue.Queue = queue.Queue()
        self.results: list[tuple[int, object, int]] = []
        self._results_lock = threading.Lock()

        self._paused = threading.Event()   # set -> paused
        self._stopped = threading.Event()  # set -> shut down

        self._work_seconds = work_seconds
        self._workers = [
            threading.Thread(target=self._run, args=(i,), name=f"worker-{i}")
            for i in range(num_workers)
        ]

    # ---- public API -------------------------------------------------

    def start(self) -> None:
        for t in self._workers:
            t.start()

    def submit(self, item) -> None:
        self.queue.put(item)

    def pause(self) -> None:
        """Signal all workers to stop taking new items.

        Each worker may finish at most its current in-flight item.
        """
        self._paused.set()

    def resume(self) -> None:
        self._paused.clear()

    def stop(self, timeout: float | None = None) -> bool:
        """Terminate all workers and join them. Returns True if all joined."""
        self._stopped.set()
        self._paused.clear()  # unblock any worker parked in the pause gate
        joined = True
        for t in self._workers:
            t.join(timeout)
            joined = joined and not t.is_alive()
        return joined

    @property
    def workers(self) -> list[threading.Thread]:
        return list(self._workers)

    def results_snapshot(self) -> list[tuple[int, object, int]]:
        """Thread-safe copy of results collected so far."""
        with self._results_lock:
            return list(self.results)

    # ---- worker loop ------------------------------------------------

    def _run(self, worker_id: int) -> None:
        while not self._stopped.is_set():
            # Pause gate: do not pull new items while paused.
            if self._paused.is_set():
                if self._stopped.wait(0.002):  # wakes instantly on stop()
                    break
                continue

            try:
                item = self.queue.get(timeout=0.01)
            except queue.Empty:
                continue

            if self._stopped.is_set():
                break

            # Process exactly one item ("one item-processing cycle").
            if self._work_seconds > 0:
                time.sleep(self._work_seconds)

            with self._results_lock:
                self.results.append((worker_id, item, time.time_ns()))

        # Drain guard: nothing left dangling; loop exits only via _stopped.
